import sys, os, json, importlib, importlib.metadata as md, platform, sysconfig
from pathlib import Path
import tempfile
tempfile.tempdir="/tmp"
blocked=[]
temporary_writes=[]
def audit(event,args):
    if event == "open":
        p,mode,flags=args
        if (isinstance(mode,str) and any(c in mode for c in "wax+")) or (isinstance(flags,int) and flags & (os.O_WRONLY|os.O_RDWR|os.O_CREAT|os.O_TRUNC|os.O_APPEND)):
            if str(p)=="/dev/null": return
            if str(p).startswith("/tmp/"):
                temporary_writes.append([event,str(p)])
                return
            blocked.append([event,str(p)])
            raise PermissionError("read-only audit: persistent file write prohibited")
        if isinstance(p,(str,bytes)) and ("/faces_256/" in str(p) or "/manifests/" in str(p)):
            raise PermissionError("read-only audit: benchmark input prohibited")
    if event in ("os.mkdir","os.remove","os.rename","os.rmdir","os.chmod","os.chown","os.symlink","os.link"):
        if str(args[0]).startswith("/tmp/") or (event in ("os.remove","os.rmdir") and isinstance(args[-1],int) and args[-1]>=0):
            temporary_writes.append([event,str(args)])
            return
        blocked.append([event,str(args)])
        raise PermissionError("read-only audit: persistent mutation prohibited")
sys.addaudithook(audit)
out={"python":platform.python_version(),"executable":sys.executable,"packages":{}}
names={"torch":"torch","torchvision":"torchvision","tensorflow":"tensorflow","cv2":"opencv-python-headless","numpy":"numpy","scipy":"scipy","sklearn":"scikit-learn","pandas":"pandas","pyarrow":"pyarrow","PIL":"Pillow","yaml":"PyYAML","tensorfn":"tensorfn","Cython":"Cython","onnxruntime":"onnxruntime","lpips":"lpips","PIL.ImageCms":"Pillow","Sim3DR_Cython":"Sim3DR_Cython","ninja":"ninja"}
for name,dist in names.items():
    try:
        m=importlib.import_module(name)
        v=getattr(m,"__version__",None)
        if v is None:
            try: v=md.version(dist)
            except md.PackageNotFoundError: v="NO_VERSION_EXPOSED"
        out["packages"][name]={"status":"AVAILABLE","version":str(v),"module_file":getattr(m,"__file__",None)}
    except Exception as e:
        out["packages"][name]={"status":"MISSING","error":type(e).__name__+": "+str(e)}
if out["packages"]["torch"]["status"]=="AVAILABLE":
    import torch
    out["torch"]={"version":torch.__version__,"cuda_runtime":torch.version.cuda,"cuda_available":torch.cuda.is_available(),"gpu_name":torch.cuda.get_device_name(0),"compute_capability":list(torch.cuda.get_device_capability(0)),"cudnn":torch.backends.cudnn.version(),"matmul_allow_tf32":torch.backends.cuda.matmul.allow_tf32,"cudnn_allow_tf32":torch.backends.cudnn.allow_tf32,"cudnn_benchmark":torch.backends.cudnn.benchmark,"cudnn_deterministic":torch.backends.cudnn.deterministic}
out["python_headers"]={"include":sysconfig.get_path("include"),"Python_h_exists":Path(sysconfig.get_path("include"),"Python.h").is_file()}
out["blocked_write_attempts"]=blocked
out["temporary_import_operations"]=temporary_writes
print(json.dumps(out,indent=2))

